sys_script.script:
(function physicalCountLifecycle() {
    // Only process status changes
    if (!current.status.changes()) {
        // Validate counted_quantity if being updated (must not be negative)
        if (current.counted_quantity.changes()) {
            var countedQtyStr = current.getValue('counted_quantity');
            if (countedQtyStr !== null && countedQtyStr !== '') {
                var countedQty = parseInt(countedQtyStr, 10);
                if (isNaN(countedQty) || countedQty < 0) {
                    gs.error('[Retail Store Assistant] Physical Count Lifecycle: rejected — counted_quantity must be non-negative, got: ' + countedQtyStr + ' for count ' + current.getValue('count_number'));
                    gs.addErrorMessage('Physical Count: counted quantity must be a non-negative integer.');
                    current.setAbortAction(true);
                    return;
                }
            }
        }
        gs.debug('[Retail Store Assistant] Physical Count Lifecycle: no status change for count ' + current.getValue('count_number') + ', skipping lifecycle logic');
        return;
    }

    var oldStatus = previous.getValue('status');
    var newStatus = current.getValue('status');
    var countNumber = current.getValue('count_number');

    gs.info('[Retail Store Assistant] Physical Count Lifecycle: processing transition "' + oldStatus + '" → "' + newStatus + '" for count ' + countNumber);

    // Define valid transitions
    var validTransitions = {
        'open': ['in_progress', 'cancelled'],
        'in_progress': ['completed', 'cancelled'],
        'completed': [],
        'cancelled': []
    };

    var allowed = validTransitions[oldStatus] || [];
    var isValid = false;
    for (var i = 0; i < allowed.length; i++) {
        if (allowed[i] === newStatus) {
            isValid = true;
            break;
        }
    }

    if (!isValid) {
        gs.error('[Retail Store Assistant] Physical Count Lifecycle: invalid transition "' + oldStatus + '" → "' + newStatus + '" for count ' + countNumber);
        gs.addErrorMessage('Physical Count lifecycle violation: cannot transition from "' + oldStatus + '" to "' + newStatus + '".');
        current.setAbortAction(true);
        return;
    }

    var now = new GlideDateTime();

    // Handle transition to In Progress: capture expected_quantity snapshot
    if (newStatus === 'in_progress') {
        var store = current.getValue('store');
        var sku = current.getValue('sku');

        gs.debug('[Retail Store Assistant] Physical Count Lifecycle: capturing expected_quantity snapshot for count ' + countNumber + ' store=' + store + ' sku=' + sku);

        // Snapshot expected_quantity from Inventory Position.on_hand
        var position = new GlideRecord('x_1945330_retail_0_inv_pos');
        position.addQuery('store', store);
        position.addQuery('sku', sku);
        position.setLimit(1);
        position.query();

        var expectedQty = 0;
        if (position.next()) {
            expectedQty = parseInt(position.getValue('on_hand'), 10) || 0;
            gs.debug('[Retail Store Assistant] Physical Count Lifecycle: found inventory position — on_hand=' + expectedQty);
        } else {
            gs.warn('[Retail Store Assistant] Physical Count Lifecycle: no inventory position found for store=' + store + ' sku=' + sku + ' — defaulting expected_quantity to 0');
        }

        current.setValue('expected_quantity', expectedQty.toString());
        current.setValue('counted_on', now.getDisplayValue());

        gs.info('[Retail Store Assistant] Physical Count Lifecycle: count ' + countNumber + ' moved to In Progress — expected_quantity=' + expectedQty + ' counted_on=' + now.getDisplayValue());
    }

    // Handle transition to Completed: calculate variance, finalize
    if (newStatus === 'completed') {
        // Validate counted_quantity is provided
        var countedQtyStr = current.getValue('counted_quantity');
        if (countedQtyStr === null || countedQtyStr === '') {
            gs.error('[Retail Store Assistant] Physical Count Lifecycle: cannot complete count ' + countNumber + ' — counted_quantity is required');
            gs.addErrorMessage('Physical Count cannot be completed: counted quantity must be entered before finalizing.');
            current.setAbortAction(true);
            return;
        }

        var countedQty = parseInt(countedQtyStr, 10);
        if (isNaN(countedQty) || countedQty < 0) {
            gs.error('[Retail Store Assistant] Physical Count Lifecycle: cannot complete count ' + countNumber + ' — counted_quantity must be non-negative, got: ' + countedQtyStr);
            gs.addErrorMessage('Physical Count cannot be completed: counted quantity must be a non-negative integer.');
            current.setAbortAction(true);
            return;
        }

        // Calculate variance = counted_quantity - expected_quantity
        var expectedQty = parseInt(current.getValue('expected_quantity'), 10) || 0;
        var variance = countedQty - expectedQty;

        current.setValue('variance', variance.toString());
        current.setValue('completed_on', now.getDisplayValue());

        gs.info('[Retail Store Assistant] Physical Count Lifecycle: count ' + countNumber + ' completed — counted_quantity=' + countedQty + ' expected_quantity=' + expectedQty + ' variance=' + variance);

        // CRITICAL: Do NOT modify Inventory Position
        // CRITICAL: Do NOT create an Inventory Transaction
        // The discrepancy path handles inventory corrections
        if (variance !== 0) {
            gs.info('[Retail Store Assistant] Physical Count Lifecycle: non-zero variance (' + variance + ') detected for count ' + countNumber + ' — discrepancy evaluation required');
        }
    }

    // Handle cancellation
    if (newStatus === 'cancelled') {
        gs.info('[Retail Store Assistant] Physical Count Lifecycle: count ' + countNumber + ' cancelled from status "' + oldStatus + '"');
    }
})();
